script:
(function () {
  'use strict';
  // Roth 403(b) vs traditional 403(b) with the 403(b) limits, including the 15-year catch-up.
  //   Limit for the year you reach age a with s years of service:
  //     base + 15-year catch-up + age catch-up (age 50+, or the higher amount at 60-63).
  //     15-year catch-up (qualifying employer, s >= 15) = least of $3,000; $15,000 minus the amount
  //     already used; $5,000 x s minus all elective deferrals to this employer in earlier years.
  //     Deferrals above the base count first as 15-year catch-up, then as age catch-up (Pub. 571).
  //   Same deferral into either account at the start of each year, growing at r.
  //   Roth: all of it is Roth; after tax = balance.
  //   Traditional: pre-tax, except that age catch-ups must be Roth if prior-year FICA wages from the
  //     employer exceeded the threshold; after tax = pre-tax balance x (1 - retirement rate) + Roth part
  //     + optional side account of the yearly tax savings (pre-tax part x current rate) growing at
  //     r x (1 - tax rate on returns). Break-even retirement rate = side account / pre-tax balance.
  // Checked in Node (fake DOM, whole script, tests/rtb.test.js): age 45, 15 years, $40,000 prior,
  //   qualifying employer -> 2026 limit $27,500 (= Pub. 571's 2026 maximum with the 15-year rule);
  //   maxing from 45 with $40,000 prior -> only 2 years of $3,000 before the $5,000 x years test binds;
  //   $0 prior -> 4 years ($12,000); $13,000 already used -> only $2,000 more (lifetime cap); $75,000 prior at 15 years
  //   -> $0 extra; age 61 -> $24,500 + $11,250 = $35,750; $10,000 a year at 6% for
  //   20 years, start of year = $389,927 in both; with 0% side-account tax the break-even rate equals the
  //   current rate (22%); wages $160,000 at 55 with max -> $8,000 a year forced Roth in the traditional path.
  //
  // ---- 2026 403(b) LIMITS (tax year 2026) -----------------------------------------------------------
  // IRS Notice 2025-67: elective deferral limit $24,500 (IRC 402(g)(1)); age-50 catch-up $8,000 and
  // age 60-63 catch-up $11,250 (IRC 414(v)); Roth catch-up wage threshold $150,000 of 2025 FICA wages
  // (IRC 414(v)(7)). 15-year rule (IRC 402(g)(7), IRS Pub. 571 Rev. January 2026): $3,000 a year,
  // $15,000 lifetime, $5,000 x years of service test. These amounts are held at 2026 levels.
  var LIMITS = { year: 2026, base: 24500, catchUp50: 8000, catchUp60to63: 11250, rothCatchUpWages: 150000,
                 svcYearly: 3000, svcLifetime: 15000, svcPerYear: 5000, svcYears: 15 };
  // ------------------------------------------------------------------------------------------------

  function ageCatchUp(age) {
    if (age >= 60 && age <= 63) return LIMITS.catchUp60to63;
    return age >= 50 ? LIMITS.catchUp50 : 0;
  }
  function serviceCatchUp(qualifies, service, priorDeferrals, used) {
    if (!qualifies || service < LIMITS.svcYears) return 0;
    return Math.max(0, Math.min(LIMITS.svcYearly, LIMITS.svcLifetime - used, LIMITS.svcPerYear * service - priorDeferrals));
  }

  // p: age, retireAge, contrib, useMax, qualifies, service, prior, used, rothCatch (bool),
  //    rate, taxNow, taxLater, investTax (decimals), invest (bool)
  function compare(p) {
    var roth = 0, pre = 0, rothPart = 0, side = 0, total = 0, used = p.used, prior = p.prior, used15 = 0, rows = [], capped = false;
    var sideRate = p.rate * (1 - p.investTax);
    for (var y = 0; y < p.retireAge - p.age; y++) {
      var age = p.age + y, svc = serviceCatchUp(p.qualifies, p.service + y, prior, used), ac = ageCatchUp(age);
      var limit = LIMITS.base + svc + ac;
      var c = p.useMax ? limit : Math.min(p.contrib, limit);
      if (!p.useMax && p.contrib > limit + 0.005) capped = true;
      var over = Math.max(0, c - LIMITS.base), s15 = Math.min(svc, over), catchPart = over - s15;
      var forced = p.rothCatch ? catchPart : 0;
      roth = (roth + c) * (1 + p.rate);
      pre = (pre + c - forced) * (1 + p.rate);
      rothPart = (rothPart + forced) * (1 + p.rate);
      if (p.invest) side = (side + (c - forced) * p.taxNow) * (1 + sideRate);
      used += s15; used15 += s15; prior += c; total += c;
      var trad = pre * (1 - p.taxLater) + rothPart + side;
      rows.push({ age: age, limit: limit, c: c, s15: s15, roth: roth, trad: trad, diff: roth - trad });
    }
    var tradAfter = pre * (1 - p.taxLater) + rothPart + side;
    return { roth: roth, pre: pre, rothPart: rothPart, side: side, trad: tradAfter, diff: roth - tradAfter, total: total,
             used15: used15, capped: capped, breakEven: pre > 0 ? side / pre : NaN, rows: rows };
  }

  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  function fmt(x) { return money.format(Math.abs(x) < 0.5 ? 0 : x); }
  function pct(x) { return (Math.round(x * 1000) / 10) + '%'; }
  function num(id) { var v = parseFloat(document.getElementById(id).value); return isNaN(v) ? NaN : v; }
  function set(id, t) { document.getElementById(id).textContent = t; }

  function update() {
    var age = num('rtbAge'), retireAge = num('rtbRetireAge'), contrib = num('rtbContrib'), service = num('rtbService'),
        taxNow = num('rtbTaxNow'), taxLater = num('rtbTaxLater'), rate = num('rtbRate'), prior = num('rtbPrior'),
        used = num('rtbUsed'), wages = num('rtbWages'), investTax = num('rtbInvestTax'),
        useMax = document.getElementById('rtbMax').checked, invest = document.getElementById('rtbInvest').checked,
        qualifies = document.getElementById('rtbEmployer').value === 'yes';
    document.getElementById('rtbContrib').disabled = useMax;
    var error = document.getElementById('rtbError');
    var bad = [age, retireAge, service, taxNow, taxLater, rate, prior, used, wages, investTax].some(isNaN) ||
              (!useMax && (isNaN(contrib) || contrib < 0)) || age !== Math.round(age) || retireAge !== Math.round(retireAge) ||
              age < 16 || age > 99 || retireAge <= age || retireAge > 100 || service < 0 || service > 70 ||
              service !== Math.round(service) || prior < 0 || used < 0 || used > LIMITS.svcLifetime || wages < 0 ||
              rate < -20 || rate > 30 || taxNow < 0 || taxNow > 70 || taxLater < 0 || taxLater > 70 || investTax < 0 || investTax > 70;
    error.hidden = !bad;
    if (bad) {
      error.textContent = 'Enter whole-number ages from 16 to 99 with retirement later (up to 100), whole years of service up to 70, ' +
                          'non-negative amounts, 15-year catch-up used up to $15,000, a return from -20 to 30% and tax rates up to 70%.';
      return;
    }
    var rothCatch = wages > LIMITS.rothCatchUpWages;
    var r = compare({ age: age, retireAge: retireAge, contrib: contrib, useMax: useMax, qualifies: qualifies, service: service,
                      prior: prior, used: used, rothCatch: rothCatch, rate: rate / 100, taxNow: taxNow / 100,
                      taxLater: taxLater / 100, investTax: investTax / 100, invest: invest });
    var tie = Math.abs(r.diff) < 0.5;
    set('rtbWinner', tie ? 'Even' : r.diff > 0 ? 'Roth 403(b)' : 'Traditional 403(b)');
    set('rtbDiff', fmt(Math.abs(r.diff)));
    set('rtbRoth', fmt(r.roth));
    set('rtbTrad', fmt(r.trad));
    set('rtbAgeLabel', 'At age ' + retireAge + ', after tax');
    var svc0 = serviceCatchUp(qualifies, service, prior, used), ac0 = ageCatchUp(age);
    set('rtbLimBase', fmt(LIMITS.base));
    set('rtbLim15', !qualifies ? 'Not offered by this employer type' : service < LIMITS.svcYears ? 'Needs 15 years of service' :
        svc0 > 0 ? fmt(svc0) : 'None left (cap or $5,000-a-year test)');
    set('rtbLimAge', ac0 > 0 ? fmt(ac0) + (age >= 60 && age <= 63 ? ' (ages 60 to 63)' : ' (age 50 or over)') : 'From age 50');
    set('rtbLimTotal', fmt(LIMITS.base + svc0 + ac0));
    set('rtbTotal', fmt(r.total));
    set('rtbUsed15', fmt(r.used15));
    set('rtbPreBal', fmt(r.pre) + (r.rothPart > 0.5 ? ' plus ' + fmt(r.rothPart) + ' Roth catch-ups' : ''));
    set('rtbSide', invest ? fmt(r.side) : 'Not invested');
    set('rtbBreakEven', isFinite(r.breakEven) ? 'Roth wins above ' + pct(r.breakEven) : '–');
    var rc = document.getElementById('rtbRothCatch');
    var catchYears = r.rows.some(function (x) { return x.c - x.s15 > LIMITS.base + 0.005; });
    rc.hidden = !(rothCatch && catchYears);
    set('rtbRothCatch', 'Your 2025 wages are above ' + fmt(LIMITS.rothCatchUpWages) + ', so from 2026 your age-50 catch-up deferrals ' +
        'must be Roth even if you choose traditional. The traditional figures include them as Roth money.');
    var cn = document.getElementById('rtbCapNote');
    cn.hidden = !r.capped;
    set('rtbCapNote', 'Your deferral is above your limit in some years, so it is capped at the limit in those years.');
    var body = document.getElementById('rtbSchedule');
    body.textContent = '';
    r.rows.forEach(function (x) {
      var tr = document.createElement('tr');
      [x.age, fmt(x.limit), fmt(x.c), fmt(x.s15), fmt(x.roth), fmt(x.trad), fmt(x.diff)].forEach(function (v) {
        var td = document.createElement('td'); td.textContent = v; tr.appendChild(td);
      });
      body.appendChild(tr);
    });
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('rtbForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
